  "model": "mistral",
  "prompt": "You are a receipt analyzer. Extract structured data from the following receipt text/PDF content. Return ONLY a valid JSON object (no markdown, no explanation) with these exact keys:\nvendor (company/store name), date (YYYY-MM-DD format), amount (number only, no currency symbol), currency (INR or USD), category (one of: groceries, utilities, office, meals, travel, medical, entertainment, other), tax (GST/tax amount or 0), description (one line summary), context (business or family or personal).\nIf you cannot extract a field, use null for it.\n\nReceipt content follows:\n{{ Buffer.from($json.data, 'base64').toString('utf8').substring(0, 4000) }}",
  "stream": false,
  "options": { "temperature": 0.1, "num_predict": 512 }
}

parameters.jsCode:
const resp = $input.first().json;
let text = resp.response || '';
// Extract first valid JSON object
const m = text.match(/\{[\s\S]*\}/);
if (!m) return [{ json: { error: 'No JSON in response', raw: text.substring(0, 500) } }];
try {
  const data = JSON.parse(m[0]);
  // Sanitize
  return [{
    json: {
      vendor: data.vendor || 'Unknown',
      date: data.date || new Date().toISOString().split('T')[0],
      amount: parseFloat(data.amount) || 0,
      currency: data.currency || 'INR',
      category: data.category || 'other',
      tax: parseFloat(data.tax) || 0,
      description: data.description || '',
      context: data.context || 'personal',
      raw: text.substring(0, 200)
    }
  }];
} catch(e) {
  return [{ json: { error: e.message, raw: text.substring(0, 500) } }];
}

